// Desi Craft - Guided Help & Voice Assistance Service
// Provides localized step tours, Web Speech Synthesis controller, and audio controls across 10 Indian languages

import { LanguageCode } from '../types';
import { universalVoiceEngine } from './voiceLanguageService';

export interface TourStep {
  id?: string;
  order?: number;
  target: string; // CSS data-guide attribute
  title: Record<LanguageCode, string>;
  content: Record<LanguageCode, string>;
  voiceScript: Record<LanguageCode, string>;
  placement?: 'top' | 'bottom' | 'left' | 'right' | 'center';
}

export interface GuideTour {
  id: string;
  name: Record<LanguageCode, string>;
  description: Record<LanguageCode, string>;
  pageContext: 'customer-home' | 'heritage-map' | 'artisan-dashboard' | 'photo-enhancer' | 'voice-creator' | 'product-detail' | 'seller-collaboration';
  mode: 'CUSTOMER' | 'ARTISAN' | 'ANY';
  steps: TourStep[];
}

