  kn: 'ನಿಮ್ಮ ಸಾಧನದಲ್ಲಿ ಈ ಭಾಷೆಗೆ ಧ್ವನಿ ಮಾರ್ಗದರ್ಶನ ಲಭ್ಯವಿಲ್ಲ. ಲಿಖಿತ ಮಾರ್ಗದರ್ಶನ ಇನ್ನೂ ಲಭ್ಯವಿದೆ.',
