// ============================================================================
// WEB SPEECH SYNTHESIS CONTROLLER
// ============================================================================

class SpeechGuidanceController {
  private currentUtterance: SpeechSynthesisUtterance | null = null;
  private isPaused = false;
  private isSpeaking = false;
  private availableVoices: SpeechSynthesisVoice[] = [];
  private listeners: Set<(speaking: boolean, paused: boolean) => void> = new Set();

  constructor() {
    if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
      this.loadVoices();
      window.speechSynthesis.onvoiceschanged = () => {
        this.loadVoices();
      };
    }
    // Synchronize speaking state with universal voice engine
    universalVoiceEngine.subscribe((speaking) => {
      this.isSpeaking = speaking;
      this.notify();
    });
  }

  private loadVoices() {
    if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
      this.availableVoices = window.speechSynthesis.getVoices();
    }
  }

  public subscribe(listener: (speaking: boolean, paused: boolean) => void): () => void {
    this.listeners.add(listener);
    listener(this.isSpeaking, this.isPaused);
    return () => {
      this.listeners.delete(listener);
    };
  }

  private notify() {
    this.listeners.forEach((l) => l(this.isSpeaking, this.isPaused));
  }

  public isSupported(): boolean {
    return true;
  }

  public isVoiceAvailableForLanguage(lang: LanguageCode): boolean {
    return true; // 100% available for all 10 languages via universal engine
  }

  public speak(
    text: string,
    lang: LanguageCode,
    onStart?: () => void,
    onEnd?: () => void,
    onError?: (err: any) => void
  ): boolean {
    this.stop();
    this.isSpeaking = true;
    this.isPaused = false;
    this.notify();

    universalVoiceEngine.play({
      text,
      lang,
      onStart: () => {
        this.isSpeaking = true;
        this.isPaused = false;
        this.notify();
        onStart?.();
      },
      onEnd: () => {
        this.isSpeaking = false;
        this.isPaused = false;
        this.notify();
        onEnd?.();
      },
      onError: (err) => {
        this.isSpeaking = false;
        this.isPaused = false;
        this.notify();
        onError?.(err);
      },
    });
    return true;
  }

  public pause() {
    universalVoiceEngine.stop();
    if (typeof window !== 'undefined' && 'speechSynthesis' in window && window.speechSynthesis.speaking && !window.speechSynthesis.paused) {
      window.speechSynthesis.pause();
    }
    this.isPaused = true;
    this.notify();
  }

  public resume() {
    this.isPaused = false;
    this.notify();
  }

  public stop() {
    universalVoiceEngine.stop();
    if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
      window.speechSynthesis.cancel();
    }
    this.isSpeaking = false;
    this.isPaused = false;
    this.currentUtterance = null;
    this.notify();
  }

  public getStatus() {
    return {
      isSpeaking: this.isSpeaking,
      isPaused: this.isPaused,
      isSupported: true,
    };
  }
}

export const speechController = new SpeechGuidanceController();
